from typing import List

class Solution:
    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        result = [0] * len(nums)

        for i in range(len(nums)):
            if nums[i] > 0:
                result[i] = nums[i]
            elif nums[i] < 0:
                result[i] = abs(nums[i])
            else:
                result[i] = nums[i]

        return result
